import{_ as e,o as n,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Enhancing Ceph for Infinite Scalability at LINE - Jinmyeong Lee & Sungjoon Koh, LINE Plus","description":"","frontmatter":{"title":"Enhancing Ceph for Infinite Scalability at LINE - Jinmyeong Lee & Sungjoon Koh, LINE Plus","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","Scalability","Distributed Storage","Object Storage","Storage Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Enhancing_Ceph_for_Infinite_Scalability_at_LINE_-_Jinmyeong_Lee_Sungjoon_Koh_LINE_Plus.md","filePath":"posts/2025/Enhancing_Ceph_for_Infinite_Scalability_at_LINE_-_Jinmyeong_Lee_Sungjoon_Koh_LINE_Plus.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Enhancing_Ceph_for_Infinite_Scalability_at_LINE_-_Jinmyeong_Lee_Sungjoon_Koh_LINE_Plus.md"};function r(l,a,_,h,s,c){return n(),t("div",null,[...a[0]||(a[0]=[o('<h2 id="会议概览" tabindex="-1">会议概览 <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;会议概览&quot;">​</a></h2><p>在Sephalocon 2025技术分享会上，LINE公司的存储架构师Lee和Sunjun分享了如何通过构建多层架构解决Ceph RGW的单集群扩展限制。</p><h2 id="关键技术背景" tabindex="-1">关键技术背景 <a class="header-anchor" href="#关键技术背景" aria-label="Permalink to &quot;关键技术背景&quot;">​</a></h2><p>LINE公司在运营中遇到了Ceph RGW的单集群容量限制、缺乏高级监控/认证功能以及与Yahoo Japan合并后引入的Dragon存储系统（高性能S3兼容）等挑战。</p><h2 id="架构创新" tabindex="-1">架构创新 <a class="header-anchor" href="#架构创新" aria-label="Permalink to &quot;架构创新&quot;">​</a></h2><ul><li><strong>路由层(Router)</strong>：通过bucket location map实现请求路由，支持多子集群统一端点暴露，扩展Create Bucket API支持存储类标识。</li><li><strong>迁移系统</strong>：候选选择器(Candidate Selector)基于时间局部性特征选择迁移目标，迁移API设计保留所有属性，Arclone定制化实现迁移。</li></ul><h2 id="加密增强方案" tabindex="-1">加密增强方案 <a class="header-anchor" href="#加密增强方案" aria-label="Permalink to &quot;加密增强方案&quot;">​</a></h2><p>建议增加AES-CTR支持，AES-GCM主密钥加密，HMAC-based SSE-C密钥验证，处理Dragon(AES-CTR)与Ceph(AES-CBC)的差异。</p><h2 id="生产部署" tabindex="-1">生产部署 <a class="header-anchor" href="#生产部署" aria-label="Permalink to &quot;生产部署&quot;">​</a></h2><p>迁移工作流包括MongoDB状态更新、FaaS触发迁移、Arclone执行和验证+源端清理。性能保障方面，迁移流量与生产流量隔离，异步迁移不影响CRUD操作。</p><h2 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h2><ul><li>社区贡献：提交加密增强方案，开发分层存储框架提案。</li><li>优化方向：Fast List机制深度优化，存储类与AWS标准的兼容性改进。</li><li>协作计划：参与上游Ceph社区会议，探讨存储类transition机制的协同方案。</li></ul><h2 id="会议结论" tabindex="-1">会议结论 <a class="header-anchor" href="#会议结论" aria-label="Permalink to &quot;会议结论&quot;">​</a></h2><p>LINE通过构建router抽象层和智能迁移系统，实现了Ceph与Dragon存储的优势互补，在保持S3兼容性的同时突破单集群限制，提高了性能与成本优化效益。</p>',14)])])}const d=e(i,[["render",r]]);export{p as __pageData,d as default};
